import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    X = int(input_data[0])

    total_sum = 0
    for i in range(1, 10):
        for j in range(1, 10):
            if i * j != X:
                total_sum += i * j
    print(total_sum)

if __name__ == '__main__':
    main()
